import { StoryRing } from "march/ui"

// arkadaş hikâyeleri: basılan halka "görüldü" olur
const friends = ["Elif Arslan", "Can Demir", "Deniz Kaya", "Ada Yıldız"]

export function FriendsTray() {
  let $seen: string[] = []
  return <div sx={{ flex: "row", gap: 3 }}>
    {friends.map((f, i) => <StoryRing name={f} state={$seen.includes(f) ? "seen" : i === 2 ? "close" : "new"} onClick={() => $seen = [...$seen, f]} />)}
  </div>
}

import { StoryRing, Card } from "march/ui"
import { star } from "march/icons"

// kendi hikâyen: + rozeti, basınca yükleniyor halkası
export function MyStory() {
  let $loading = false
  return <Card m:theme="night">
    <StoryRing name="Siz" add addIcon={star} size="lg" label="Hikâyen" loading={$loading} m:color="brand-purple"
      onClick={() => { $loading = true; setTimeout(() => $loading = false, 1200) }} />
  </Card>
}

import { StoryRing, Avatar } from "march/ui"
import { camera } from "march/icons"

// StoryRing'in özellikleri: name, src, state, size, label, add, loading, onClick, ariaLabel, addIcon, avatar, class
export function StoryRingLab() {
  let $clicks = 0
  return <div sx={{ flex: ["row", "center"], gap: 3 }}>
    <StoryRing class="lab-btn" name="Elif" src="/media/social/sunset.svg" state="new" size="lg" label="elif" ariaLabel="Elif'in hikâyesi"
      loading={false} onClick={() => $clicks++} />
    {/* addIcon: + rozetinde kendi ikonun (burada kamera) */}
    <StoryRing class="lab-img" name="Can" state="none" add addIcon={camera} avatar={<Avatar name="Can" color="brand-blue" />} />
    <span class="lab-clicks">{$clicks}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { StoryRingLab } from "./StoryRingLab.tsx"

// StoryRingLab'in testleri: kaydedince Testler sekmesinde çalışır
test("onClick ile halka bir düğme olur, ariaLabel adını verir", async () => {
  const s = renderTest(() => <StoryRingLab />)
  await s.click("Elif'in hikâyesi")
  expect(s.get(".lab-clicks")?.textContent).toBe("1")
})

test("onClick yoksa resim rolünde", () => {
  const s = renderTest(() => <StoryRingLab />)
  expect(s.get(".lab-img")?.getAttribute("role")).toBe("img")
})

test("add rozeti addIcon ile çizilir", () => {
  const s = renderTest(() => <StoryRingLab />)
  expect(s.get(".lab-img .m-sring-add svg")).not.toBe(null)
})
